import React from 'react';
import { BrowserRouter, Navigate, Route, Routes } from 'react-router-dom';
import { AppProvider } from './lib/AppContext';
import AdminLayout from './components/layout/AdminLayout';
import Login from './pages/login';
import Dashboard from './pages/dashboard';
import ReportsPage from './pages/reports';
import ReportDetailModal from './components/reports/ReportDetailModal';
import Analytics from './pages/analytics';
import Officers from './pages/officers';
import ChatPage from './pages/reports/chat';

export default function App() {
  return <BrowserRouter><AppProvider><Routes><Route path="/login" element={<Login/>}/><Route path="/" element={<Navigate to="/login" replace/>}/><Route element={<AdminLayout/>}><Route path="/dashboard" element={<Dashboard/>}/><Route path="/reports" element={<ReportsPage/>}/><Route path="/reports/:id" element={<ReportDetailModal/>}/><Route path="/reports/:id/chat" element={<ChatPage/>}/><Route path="/analytics" element={<Analytics/>}/><Route path="/officers" element={<Officers/>}/></Route><Route path="*" element={<Navigate to="/dashboard" replace/>}/></Routes></AppProvider></BrowserRouter>;
}
